    home_seen: bool,
    hidden_weight: usize,
    hidden_seen: bool,
    extstar_weight: usize,
    extstar_seen: bool,
    conf_weight: usize,
    conf_seen: bool,
    xml_weight: usize,
    xml_seen: bool,
    json_weight: usize,
    json_seen: bool,
    yaml_weight: usize,
    yaml_seen: bool,
    ini_weight: usize,
    ini_seen: bool,
    shell_weight: usize,
    shell_seen: bool,
    git_weight: usize,
    git_seen: bool,
    nginx_weight: usize,
    nginx_seen: bool,
    apache_weight: usize,
    apache_seen: bool,
    backup_weight: usize,
    backup_seen: bool,
    bak_weight: usize,
    bak_seen: bool,
    old_weight: usize,
    old_seen: bool,
    orig_weight: usize,
