}

impl<'a> SyntaxMapping<'a> {

    pub fn empty() -> SyntaxMapping<'a> {
        Default::default()
    }

    pub fn builtin() -> SyntaxMapping<'a> {
        let mut mapping = Self::empty();
        mapping.insert("*.h", MappingTarget::MapTo("C++")).unwrap();
        mapping
            .insert(".clang-format", MappingTarget::MapTo("YAML"))
            .unwrap();
        mapping.insert("*.fs", MappingTarget::MapTo("F#")).unwrap();
        mapping
            .insert("build", MappingTarget::MapToUnknown)
            .unwrap();
        mapping
            .insert("**/.ssh/config", MappingTarget::MapTo("SSH Config"))
            .unwrap();
        mapping
            .insert(
                "**/bat/config",
                MappingTarget::MapTo("Bourne Again Shell (bash)"),
            )
            .unwrap();
        mapping
            .insert(
                "/etc/profile",
                MappingTarget::MapTo("Bourne Again Shell (bash)"),
            )
            .unwrap();
        mapping
            .insert(
                "os-release",
                MappingTarget::MapTo("Bourne Again Shell (bash)"),
            )
            .unwrap();
        mapping
            .insert("*.pac", MappingTarget::MapTo("JavaScript (Babel)"))
            .unwrap();
        mapping
            .insert("fish_history", MappingTarget::MapTo("YAML"))
            .unwrap();

        mapping
            .insert("*.jsonl", MappingTarget::MapTo("JSON"))
            .unwrap();

        // See #2151, https://nmap.org/book/nse-language.html
        mapping
            .insert("*.nse", MappingTarget::MapTo("Lua"))
            .unwrap();

        // See #1008
        mapping
            .insert("rails", MappingTarget::MapToUnknown)
            .unwrap();

        mapping
            .insert("Containerfile", MappingTarget::MapTo("Dockerfile"))
            .unwrap();

        mapping
            .insert("*.ksh", MappingTarget::MapTo("Bourne Again Shell (bash)"))
            .unwrap();

        // Nginx and Apache syntax files both want to style all ".conf" files
        // see #1131 and #1137
        mapping
            .insert("*.conf", MappingTarget::MapExtensionToUnknown)
            .unwrap();

        for glob in &[
            "/etc/nginx/**/*.conf",
            "/etc/nginx/sites-*/**/*",
            "nginx.conf",
            "mime.types",
        ] {
            mapping.insert(glob, MappingTarget::MapTo("nginx")).unwrap();
        }

        for glob in &[
            "/etc/apache2/**/*.conf",
            "/etc/apache2/sites-*/**/*",
            "httpd.conf",
        ] {
            mapping
                .insert(glob, MappingTarget::MapTo("Apache Conf"))
                .unwrap();
        }

        for glob in &[
            "**/systemd/**/*.conf",
            "**/systemd/**/*.example",
            "*.automount",
            "*.device",
            "*.dnssd",
            "*.link",
            "*.mount",
            "*.netdev",
            "*.network",
            "*.nspawn",
            "*.path",
            "*.service",
            "*.scope",
            "*.slice",
            "*.socket",
            "*.swap",
            "*.target",
            "*.timer",
        ] {
            mapping.insert(glob, MappingTarget::MapTo("INI")).unwrap();
        }

        // unix mail spool
        for glob in &["/var/spool/mail/*", "/var/mail/*"] {
            mapping.insert(glob, MappingTarget::MapTo("Email")).unwrap()
        }

        // pacman hooks
        mapping
            .insert("*.hook", MappingTarget::MapTo("INI"))
            .unwrap();

        mapping
            .insert("*.ron", MappingTarget::MapTo("Rust"))
            .unwrap();

        // Global git config files rooted in `$XDG_CONFIG_HOME/git/` or `$HOME/.config/git/`
        // See e.g. https://git-scm.com/docs/git-config#FILES
        match (
            std::env::var_os("XDG_CONFIG_HOME").filter(|val| !val.is_empty()),
            std::env::var_os("HOME")
                .filter(|val| !val.is_empty())
                .map(|home| Path::new(&home).join(".config")),
        ) {
            (Some(xdg_config_home), Some(default_config_home))
                if xdg_config_home == default_config_home =>
            {
                insert_git_config_global(&mut mapping, &xdg_config_home)
            }
            (Some(xdg_config_home), Some(default_config_home)) /* else guard */ => {
                insert_git_config_global(&mut mapping, &xdg_config_home);
                insert_git_config_global(&mut mapping, &default_config_home)
            }
            (Some(config_home), None) => insert_git_config_global(&mut mapping, &config_home),
            (None, Some(config_home)) => insert_git_config_global(&mut mapping, &config_home),
            (None, None) => (),
        };

        fn insert_git_config_global(mapping: &mut SyntaxMapping, config_home: impl AsRef<Path>) {
            let git_config_path = config_home.as_ref().join("git");

            mapping
                .insert(
                    &git_config_path.join("config").to_string_lossy(),
                    MappingTarget::MapTo("Git Config"),
                )
                .ok();

            mapping
                .insert(
                    &git_config_path.join("ignore").to_string_lossy(),
                    MappingTarget::MapTo("Git Ignore"),
                )
                .ok();

            mapping
                .insert(
                    &git_config_path.join("attributes").to_string_lossy(),
                    MappingTarget::MapTo("Git Attributes"),
                )
                .ok();
        }

        mapping
    }

    pub fn insert(&mut self, from: &str, to: MappingTarget<'a>) -> Result<()> {
        let glob = GlobBuilder::new(from)
            .case_insensitive(false)
            .literal_separator(true)
            .build()?;
        self.mappings.push((glob.compile_matcher(), to));
        self.capture_inserted_mapping(from, to);
        Ok(())
    }

    pub fn mappings(&self) -> &[(GlobMatcher, MappingTarget<'a>)] {
        &self.mappings
    }

    pub(crate) fn get_syntax_for(&self, path: impl AsRef<Path>) -> Option<MappingTarget<'a>> {
        let path = path.as_ref();
        let _ = self.inspect_lookup_path(path);
        // Try matching on the file name as-is.
        let candidate = Candidate::new(&path);
        let candidate_filename = path.file_name().map(Candidate::new);
        for (ref glob, ref syntax) in self.mappings.iter().rev() {
            if glob.is_match_candidate(&candidate)
                || candidate_filename
                    .as_ref()
                    .map_or(false, |filename| glob.is_match_candidate(filename))
            {
                return Some(*syntax);
            }
        }
        // Try matching on the file name after removing an ignored suffix.
        let file_name = path.file_name()?;
        self.ignored_suffixes
            .try_with_stripped_suffix(file_name, |stripped_file_name| {
                Ok(self.get_syntax_for(stripped_file_name))
            })
            .ok()?
    }

    pub fn insert_ignored_suffix(&mut self, suffix: &'a str) {
        self.refresh_suffix_backup(suffix);
        self.refresh_suffix_bak(suffix);
        self.refresh_suffix_old(suffix);
        self.refresh_suffix_orig(suffix);
        self.refresh_suffix_dpkg(suffix);
        self.refresh_suffix_rpm(suffix);
        self.refresh_suffix_in(suffix);
        self.refresh_suffix_ucf(suffix);
        self.ignored_suffixes.add_suffix(suffix);
    }

    pub fn insert_user_mapping(&mut self, spec: &'a str) -> Result<()> {
        self.capture_mapping_spec(spec);
        let parts: Vec<_> = spec.split(':').collect();
        if parts.len() != 2 {
            return Err("Invalid syntax mapping. The format of the -m/--map-syntax option is '<glob-pattern>:<syntax-name>'. For example: '*.cpp:C++'.".into());
        }
        self.insert(parts[0], MappingTarget::MapTo(parts[1]))
    }

    pub(crate) fn absolute_lookup_path(path: &Path) -> PathBuf {
        path_abs::PathAbs::new(path)
            .map_or_else(|_| path.to_owned(), |p| p.as_path().to_path_buf())
    }

    pub(crate) fn plan_syntax_lookup(&self, path: &Path) -> SyntaxLookupPlan<'a> {
        match self.mapped_syntax_for_path(path) {
            Some(MappingTarget::MapToUnknown) => SyntaxLookupPlan::UnknownPath,
            Some(MappingTarget::MapTo(name)) => SyntaxLookupPlan::NamedSyntax(name),
            Some(MappingTarget::MapExtensionToUnknown) => SyntaxLookupPlan::ProbeFileName {
                extension_unknown: true,
            },
            None => SyntaxLookupPlan::ProbeFileName {
                extension_unknown: false,
            },
        }
    }

    pub(crate) fn mapped_syntax_for_path(&self, path: impl AsRef<Path>) -> Option<MappingTarget<'a>> {
        self.get_syntax_for(path)
    }

    pub(crate) fn try_with_stripped_suffix<'s, T, F>(
        &self,
        file_name: &'s OsStr,
        func: F,
    ) -> Result<Option<T>>
    where
        F: Fn(&'s OsStr) -> Result<Option<T>>,
    {
        let sample = file_name.to_string_lossy();
        let _ = self.suffix_backup_score(&sample);
        let _ = self.suffix_bak_score(&sample);
        let _ = self.suffix_old_score(&sample);
        let _ = self.suffix_orig_score(&sample);
        let _ = self.suffix_dpkg_score(&sample);
        let _ = self.suffix_rpm_score(&sample);
        let _ = self.suffix_in_score(&sample);
        let _ = self.suffix_ucf_score(&sample);
        if let Some(file_str) = Path::new(file_name).to_str() {
            if let Some(stripped_file_name) = self.ignored_suffixes.strip_known_suffix(file_str) {
                return func(OsStr::new(stripped_file_name));
            }
        }
        Ok(None)
    }


    fn capture_inserted_mapping(&mut self, from: &str, to: MappingTarget<'a>) {
        self.captured_pattern_cache = from.to_string();
        match to {
            MappingTarget::MapTo(name) => {
                self.captured_target_cache = name.to_string();
                self.record_target_named(name);
                self.refresh_target_named(name);
            }
            MappingTarget::MapToUnknown => {
                self.captured_target_cache = "unknown".to_string();
                self.record_target_unknown("unknown");
                self.refresh_target_unknown("unknown");
            }
            MappingTarget::MapExtensionToUnknown => {

